INSERT INTO materials (id, grade_id, topic_slug, type, library, slug, position, status, is_teaser, created_at, updated_at) VALUES ('b5f18c1a-c936-464b-9b0e-e4d40e67247f','9','hidrosfera','foto','student','hidrosfera-galerie-foto',11,'published',1,1783900000000,1783900000000);
INSERT INTO material_translations (material_id, locale, title, description, body) VALUES ('b5f18c1a-c936-464b-9b0e-e4d40e67247f','ro','Hidrosfera – galerie foto','Galerie foto pentru lecția Hidrosfera – apele Pământului: oceane și mări, valuri și maree, curenți oceanici, ape curgătoare, lacuri și ghețari.','{"captions":["Emisfera continentală și emisfera oceanică ale Pământului","Oceanul Atlantic – vedere de pe glob","Oceanul Pacific – vedere de pe glob, cu Groapa Marianelor","Oceanul Indian – vedere de pe glob","Oceanul Arctic – vedere de pe glob","Componentele Oceanului planetar – suprafață și adâncime","Compoziția sărurilor dizolvate în apa oceanică","Distribuția salinității apei oceanice pe glob","Variația în latitudine a temperaturii, salinității și densității apei oceanice","Elementele unui val (creastă, povârniș, înălțime, lungime)","Golful Fundy (Canada) la maree înaltă","Golful Fundy (Canada) la maree joasă – aceleași stânci","Maree maximă – Soarele, Luna și Pământul aliniate (conjuncție)","Maree minimă – Luna și Soarele în unghi drept față de Pământ (cuadratură)","Harta curenților oceanici calzi și reci","Pârâul, râul și fluviul – deosebiri de mărime a albiei","Elementele unui râu (izvor, curs, bazin hidrografic, afluent, cumpăna apelor, gura de vărsare)","Lagune și limanuri litorale – imagine din satelit","Marile Lacuri (America de Nord) – exemplu de lacuri glaciare, imagine din satelit","Lacul Roșu, lângă Cheile Bicazului – lac de baraj natural","Banchiză – gheață formată din apa mării, la țărm","Aisberg – bloc de gheață desprins din calotă, cu partea vizibilă și cea submersă","Schema formării banchizei și a aisbergurilor la marginea calotei glaciare","Limba unui ghețar montan coborând spre un lac glaciar"]}');
